// GetSlash Get PMS info
//
// Information about this PMS setup and configuration.
//
// Corresponds with GET / (the `GetSlash` operationId).
func (c *Client) GetSlash(ctx context.Context, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewGetSlashRequest(c.Server)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

// EventsourceGetSlash Connect to Eventsource
//
// Connect to the event source to get a stream of events.
